  ($q$f01$q$, $q$family$q$, 0, $q$Parents and brothers$q$, $j$[{"id":"wi-1","type":"wordIntro","word":{"thai":"พ่อ","roman":"phɔ̂ɔ","english":"father"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-3","type":"translationChoice","thai":"พ่อ","roman":"phɔ̂ɔ","options":[{"text":"Mother.","correct":false},{"text":"Father.","correct":true},{"text":"Older sister.","correct":false},{"text":"Family.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["พ่อ"]},{"id":"sp-6","type":"speak","thai":"พ่อ","roman":"phɔ̂ɔ","meaning":"father","source":"Essential Thai (Higbie), p.82","parts":["พ่อ"]},{"id":"wi-2","type":"wordIntro","word":{"thai":"แม่","roman":"mɛ̂ɛ","english":"mother"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-4","type":"translationChoice","thai":"แม่","roman":"mɛ̂ɛ","options":[{"text":"Siblings.","correct":false},{"text":"Mother.","correct":true},{"text":"Father.","correct":false},{"text":"Older brother.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["แม่"]},{"id":"so-5","type":"sentenceOrder","prompt":"father, mother","tileUnit":"word","words":{"a":{"roman":"phɔ̂ɔ","thai":"พ่อ"},"b":{"roman":"mɛ̂ɛ","thai":"แม่"}},"poolOrder":["b","a"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.82"},{"id":"sp-7","type":"speak","thai":"แม่","roman":"mɛ̂ɛ","meaning":"mother","source":"Essential Thai (Higbie), p.82","parts":["แม่"]},{"id":"wi-8","type":"wordIntro","word":{"thai":"พี่ชาย","roman":"phîi-chaai","english":"older brother"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-10","type":"translationChoice","thai":"พี่ชาย","roman":"phîi-chaai","options":[{"text":"Older brother.","correct":true},{"text":"Father.","correct":false},{"text":"Mother.","correct":false},{"text":"Younger brother.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["พี่ชาย"]},{"id":"sp-13","type":"speak","thai":"พี่ชาย","roman":"phîi-chaai","meaning":"older brother","source":"Essential Thai (Higbie), p.82","parts":["พี่ชาย"]},{"id":"wi-9","type":"wordIntro","word":{"thai":"น้องชาย","roman":"nɔ́ɔng-chaai","english":"younger brother"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-11","type":"translationChoice","thai":"น้องชาย","roman":"nɔ́ɔng-chaai","options":[{"text":"Older brother.","correct":false},{"text":"Family.","correct":false},{"text":"Younger brother.","correct":true},{"text":"Mother.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["น้องชาย"]},{"id":"so-12","type":"sentenceOrder","prompt":"older brother, younger brother","tileUnit":"word","words":{"a":{"roman":"phîi-chaai","thai":"พี่ชาย"},"b":{"roman":"nɔ́ɔng-chaai","thai":"น้องชาย"},"x0":{"thai":"พ่อ","roman":"phɔ̂ɔ"},"x1":{"thai":"แม่","roman":"mɛ̂ɛ"}},"poolOrder":["a","b","x1","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.82"},{"id":"sp-14","type":"speak","thai":"น้องชาย","roman":"nɔ́ɔng-chaai","meaning":"younger brother","source":"Essential Thai (Higbie), p.82","parts":["น้องชาย"]},{"id":"match-15","type":"match","pairs":[{"thai":"พ่อ","roman":"phɔ̂ɔ","english":"father"},{"thai":"แม่","roman":"mɛ̂ɛ","english":"mother"},{"thai":"พี่ชาย","roman":"phîi-chaai","english":"older brother"},{"thai":"น้องชาย","roman":"nɔ́ɔng-chaai","english":"younger brother"}],"source":"Essential Thai (Higbie), p.82"}]$j$::jsonb),
  ($q$f02$q$, $q$family$q$, 1, $q$Sisters, siblings, and family$q$, $j$[{"id":"rule-16","type":"rule","title":"Phîi and nɔ́ɔng","body":"In Thai, brothers and sisters are always identified as either older or younger. Phîi is the prefix for \"older\" and nɔ́ɔng is for \"younger\". Phîi and nɔ́ɔng can also be used alone for \"he/she\" and \"you\", and phîi can be put before the names of older peers to show that they're older and respected.","source":"Essential Thai (Higbie), p.82"},{"id":"mc-29","type":"translationChoice","thai":"พ่อแม่","roman":"phɔ̂ɔ-mɛ̂ɛ","options":[{"text":"Siblings.","correct":false},{"text":"Parents.","correct":true},{"text":"Younger brother.","correct":false},{"text":"Family.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["พ่อ","แม่"]},{"id":"wi-17","type":"wordIntro","word":{"thai":"พี่สาว","roman":"phîi-sǎao","english":"older sister"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-19","type":"translationChoice","thai":"พี่สาว","roman":"phîi-sǎao","options":[{"text":"Older brother.","correct":false},{"text":"Older sister.","correct":true},{"text":"Younger sister.","correct":false},{"text":"Father.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["พี่สาว"]},{"id":"sp-22","type":"speak","thai":"พี่สาว","roman":"phîi-sǎao","meaning":"older sister","source":"Essential Thai (Higbie), p.82","parts":["พี่สาว"]},{"id":"wi-18","type":"wordIntro","word":{"thai":"น้องสาว","roman":"nɔ́ɔng-sǎao","english":"younger sister"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-20","type":"translationChoice","thai":"น้องสาว","roman":"nɔ́ɔng-sǎao","options":[{"text":"Younger sister.","correct":true},{"text":"Younger brother.","correct":false},{"text":"Mother.","correct":false},{"text":"Older sister.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["น้องสาว"]},{"id":"so-21","type":"sentenceOrder","prompt":"older sister, younger sister","tileUnit":"word","words":{"a":{"roman":"phîi-sǎao","thai":"พี่สาว"},"b":{"roman":"nɔ́ɔng-sǎao","thai":"น้องสาว"},"x0":{"thai":"น้องชาย","roman":"nɔ́ɔng-chaai"},"x1":{"thai":"พ่อ","roman":"phɔ̂ɔ"}},"poolOrder":["x0","b","a","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.82"},{"id":"sp-23","type":"speak","thai":"น้องสาว","roman":"nɔ́ɔng-sǎao","meaning":"younger sister","source":"Essential Thai (Higbie), p.82","parts":["น้องสาว"]},{"id":"wi-24","type":"wordIntro","word":{"thai":"พี่น้อง","roman":"phîi-nɔ́ɔng","english":"brothers and sisters / siblings"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-27","type":"translationChoice","thai":"พี่น้อง","roman":"phîi-nɔ́ɔng","options":[{"text":"Family.","correct":false},{"text":"Younger sister.","correct":false},{"text":"Brothers and sisters / siblings.","correct":true},{"text":"Parents.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["พี่น้อง"]},{"id":"wi-25","type":"wordIntro","word":{"thai":"ครอบครัว","roman":"khrɔ̂ɔp-khrua","english":"family"},"source":"Essential Thai (Higbie), p.82"},{"id":"mc-28","type":"translationChoice","thai":"ครอบครัว","roman":"khrɔ̂ɔp-khrua","options":[{"text":"Mother.","correct":false},{"text":"Older brother.","correct":false},{"text":"Siblings.","correct":false},{"text":"Family.","correct":true}],"source":"Essential Thai (Higbie), p.82","parts":["ครอบครัว"]},{"id":"sp-32","type":"speak","thai":"ครอบครัว","roman":"khrɔ̂ɔp-khrua","meaning":"family","source":"Essential Thai (Higbie), p.82","parts":["ครอบครัว"]},{"id":"wi-26","type":"wordIntro","word":{"thai":"กับ","roman":"gàp","english":"and / with"},"source":"Essential Thai (Higbie), general reference (connecting words)"},{"id":"mc-30","type":"translationChoice","thai":"พี่ชายกับน้องสาว","roman":"phîi-chaai gàp nɔ́ɔng-sǎao","options":[{"text":"Older brother and younger sister.","correct":true},{"text":"Parents.","correct":false},{"text":"Older sister and younger brother.","correct":false},{"text":"Family.","correct":false}],"source":"Essential Thai (Higbie), p.82","parts":["พี่ชาย","กับ","น้องสาว"]},{"id":"so-31","type":"sentenceOrder","prompt":"family and siblings","tileUnit":"word","words":{"a":{"roman":"khrɔ̂ɔp-khrua","thai":"ครอบครัว"},"b":{"roman":"gàp","thai":"กับ"},"c":{"roman":"phîi-nɔ́ɔng","thai":"พี่น้อง"},"x0":{"thai":"น้องสาว","roman":"nɔ́ɔng-sǎao"},"x1":{"thai":"พี่สาว","roman":"phîi-sǎao"}},"poolOrder":["b","x1","c","x0","a"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.82"},{"id":"sp-33","type":"speak","thai":"พี่น้องกับครอบครัว","roman":"phîi-nɔ́ɔng gàp khrɔ̂ɔp-khrua","meaning":"Siblings and family.","source":"Essential Thai (Higbie), p.82","parts":["พี่น้อง","กับ","ครอบครัว"]},{"id":"match-34","type":"match","pairs":[{"thai":"พี่สาว","roman":"phîi-sǎao","english":"older sister"},{"thai":"น้องสาว","roman":"nɔ́ɔng-sǎao","english":"younger sister"},{"thai":"พี่น้อง","roman":"phîi-nɔ́ɔng","english":"brothers and sisters / siblings"},{"thai":"ครอบครัว","roman":"khrɔ̂ɔp-khrua","english":"family"},{"thai":"กับ","roman":"gàp","english":"and / with"}],"source":"Essential Thai (Higbie), p.82"}]$j$::jsonb),
  ($q$f03$q$, $q$family$q$, 2, $q$He, she, you, and have$q$, $j$[{"id":"wi-35","type":"wordIntro","word":{"thai":"เค้า","roman":"kháo","english":"he / she"},"source":"Essential Thai (Higbie), p.47"},{"id":"wi-36","type":"wordIntro","word":{"thai":"เป็น","roman":"pen","english":"to be / is"},"source":"Essential Thai (Higbie), p.47"},{"id":"mc-151","type":"translationChoice","thai":"เค้าเป็นพ่อ","roman":"kháo pen phɔ̂ɔ","options":[{"text":"He's my older brother.","correct":false},{"text":"He's my father.","correct":true},{"text":"She's my younger sister.","correct":false},{"text":"I have an older brother.","correct":false}],"source":"Essential Thai (Higbie), p.47","parts":["เค้า","เป็น","พ่อ"]},{"id":"so-152","type":"sentenceOrder","prompt":"She's my younger sister.","tileUnit":"word","words":{"a":{"roman":"kháo","thai":"เค้า"},"b":{"roman":"pen","thai":"เป็น"},"c":{"roman":"nɔ́ɔng-sǎao","thai":"น้องสาว"},"x0":{"thai":"พ่อ","roman":"phɔ̂ɔ"},"x1":{"thai":"กับ","roman":"gàp"}},"poolOrder":["b","c","x0","a","x1"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.47"},{"id":"sp-154","type":"speak","thai":"เค้าเป็นพี่ชาย","roman":"kháo pen phîi-chaai","meaning":"He's my older brother.","source":"Essential Thai (Higbie), p.47","parts":["เค้า","เป็น","พี่ชาย"]},{"id":"sp-157","type":"speak","thai":"เค้าเป็นพ่อ","roman":"kháo pen phɔ̂ɔ","meaning":"He's my father.","source":"Essential Thai (Higbie), p.47","parts":["เค้า","เป็น","พ่อ"]},{"id":"wi-42","type":"wordIntro","word":{"thai":"คุณ","roman":"khun","english":"you"},"source":"Essential Thai (Higbie), p.46"},{"id":"wi-43","type":"wordIntro","word":{"thai":"มี","roman":"mii","english":"have / there is"},"source":"Essential Thai (Higbie), p.24"},{"id":"mc-153","type":"translationChoice","thai":"มีพี่ชาย","roman":"mii phîi-chaai","options":[{"text":"I have an older brother.","correct":true},{"text":"He's my older brother.","correct":false},{"text":"He's my father.","correct":false},{"text":"She's my younger sister.","correct":false}],"source":"Essential Thai (Higbie), p.47","parts":["มี","พี่ชาย"]},{"id":"so-155","type":"sentenceOrder","prompt":"I have an older sister and a younger brother.","tileUnit":"word","words":{"a":{"roman":"mii","thai":"มี"},"b":{"roman":"phîi-sǎao","thai":"พี่สาว"},"c":{"roman":"gàp","thai":"กับ"},"d":{"roman":"nɔ́ɔng-chaai","thai":"น้องชาย"},"x0":{"thai":"น้องสาว","roman":"nɔ́ɔng-sǎao"},"x1":{"thai":"พ่อ","roman":"phɔ̂ɔ"}},"poolOrder":["a","x1","b","x0","d","c"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.47"},{"id":"sp-156","type":"speak","thai":"คุณมีครอบครัว","roman":"khun mii khrɔ̂ɔp-khrua","meaning":"You have a family.","source":"Essential Thai (Higbie), p.47","parts":["คุณ","มี","ครอบครัว"]},{"id":"match-158","type":"match","pairs":[{"thai":"เค้า","roman":"kháo","english":"he / she"},{"thai":"เป็น","roman":"pen","english":"to be / is"},{"thai":"คุณ","roman":"khun","english":"you"},{"thai":"มี","roman":"mii","english":"have / there is"}],"source":"Essential Thai (Higbie), p.47"}]$j$::jsonb),
  ($q$f04$q$, $q$family$q$, 3, $q$How many? Numbers one and two$q$, $j$[{"id":"wi-49","type":"wordIntro","word":{"thai":"กี่","roman":"gìi","english":"how many?"},"source":"Essential Thai (Higbie), p.28"},{"id":"wi-50","type":"wordIntro","word":{"thai":"คน","roman":"kon","english":"person (classifier for people)"},"source":"Essential Thai (Higbie), p.53"},{"id":"mc-159","type":"translationChoice","thai":"คุณมีพี่น้องกี่คน","roman":"khun mii phîi-nɔ́ɔng gìi kon","options":[{"text":"How many siblings do you have?","correct":true},{"text":"I have one older brother.","correct":false},{"text":"I have two siblings.","correct":false},{"text":"How many people?","correct":false}],"source":"Essential Thai (Higbie), p.28","parts":["คุณ","มี","พี่น้อง","กี่","คน"]},{"id":"sp-162","type":"speak","thai":"กี่คน","roman":"gìi kon","meaning":"How many people?","source":"Essential Thai (Higbie), p.28","parts":["กี่","คน"]},{"id":"sp-164","type":"speak","thai":"คุณมีพี่น้องกี่คน","roman":"khun mii phîi-nɔ́ɔng gìi kon","meaning":"How many siblings do you have?","source":"Essential Thai (Higbie), p.28","parts":["คุณ","มี","พี่น้อง","กี่","คน"]},{"id":"wi-55","type":"wordIntro","word":{"thai":"หนึ่ง","roman":"nɯ̀ng","english":"one"},"source":"Essential Thai (Higbie), p.17"},{"id":"mc-161","type":"translationChoice","thai":"มีพี่ชายคนหนึ่ง","roman":"mii phîi-chaai kon nɯ̀ng","options":[{"text":"How many people?","correct":false},{"text":"I have two siblings.","correct":false},{"text":"I have one older brother.","correct":true},{"text":"How many siblings do you have?","correct":false}],"source":"Essential Thai (Higbie), p.28","parts":["มี","พี่ชาย","คน","หนึ่ง"]},{"id":"wi-56","type":"wordIntro","word":{"thai":"สอง","roman":"sɔ̌ɔng","english":"two"},"source":"Essential Thai (Higbie), p.17"},{"id":"so-160","type":"sentenceOrder","prompt":"I have two siblings.","tileUnit":"word","words":{"a":{"roman":"mii","thai":"มี"},"b":{"roman":"phîi-nɔ́ɔng","thai":"พี่น้อง"},"c":{"roman":"sɔ̌ɔng","thai"