  ($q$f07$q$, $q$family$q$, 6, $q$Home, grandma, and grandpa$q$, $j$[{"id":"rule-98","type":"rule","title":"One big family","body":"Some relationship terms are used to refer to people you're not related to — in Thai culture everyone is considered a big family. Yaai and taa are used for a woman/man your grandmother's/grandfather's age (they literally refer to your mother's mother/father), and lung, pâa, and náa are used the same way for an uncle or aunt's age.","source":"Essential Thai (Higbie), p.83"},{"id":"wi-91","type":"wordIntro","word":{"thai":"ที่นี่","roman":"thîi-nîi","english":"here"},"source":"Essential Thai (Higbie), p.83"},{"id":"sp-186","type":"speak","thai":"ลูกอยู่ที่นี่","roman":"lûuk yùu thîi-nîi","meaning":"The children are here.","source":"Essential Thai (Higbie), p.83","parts":["ลูก","อยู่","ที่นี่"]},{"id":"so-187","type":"sentenceOrder","prompt":"My younger brother is here.","tileUnit":"word","words":{"a":{"roman":"nɔ́ɔng-chaai","thai":"น้องชาย"},"b":{"roman":"yùu","thai":"อยู่"},"c":{"roman":"thîi-nîi","thai":"ที่นี่"},"x0":{"thai":"คุณ","roman":"khun"},"x1":{"thai":"สี่","roman":"sìi"}},"poolOrder":["x1","b","a","c","x0"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.83"},{"id":"wi-92","type":"wordIntro","word":{"thai":"บ้าน","roman":"bâan","english":"home / house"},"source":"Essential Thai (Higbie), p.83"},{"id":"mc-185","type":"translationChoice","thai":"พ่อแม่อยู่บ้าน","roman":"phɔ̂ɔ mɛ̂ɛ yùu bâan","options":[{"text":"Grandma is at home.","correct":false},{"text":"My parents are at home.","correct":true},{"text":"The children are here.","correct":false},{"text":"Where is grandpa?","correct":false}],"source":"Essential Thai (Higbie), p.83","parts":["พ่อ","แม่","อยู่","บ้าน"]},{"id":"wi-99","type":"wordIntro","word":{"thai":"ยาย","roman":"yaai","english":"grandmother (lit. mother's mother)"},"source":"Essential Thai (Higbie), p.83"},{"id":"mc-183","type":"translationChoice","thai":"ยายอยู่บ้าน","roman":"yaai yùu bâan","options":[{"text":"Where is grandpa?","correct":false},{"text":"Grandma is at home.","correct":true},{"text":"The children are here.","correct":false},{"text":"My parents are at home.","correct":false}],"source":"Essential Thai (Higbie), p.83","parts":["ยาย","อยู่","บ้าน"]},{"id":"sp-188","type":"speak","thai":"ยายอยู่บ้าน","roman":"yaai yùu bâan","meaning":"Grandma is at home.","source":"Essential Thai (Higbie), p.83","parts":["ยาย","อยู่","บ้าน"]},{"id":"wi-100","type":"wordIntro","word":{"thai":"ตา","roman":"taa","english":"grandfather (lit. mother's father)"},"source":"Essential Thai (Higbie), p.83"},{"id":"so-184","type":"sentenceOrder","prompt":"Where is grandpa?","tileUnit":"word","words":{"a":{"roman":"taa","thai":"ตา"},"b":{"roman":"yùu","thai":"อยู่"},"c":{"roman":"thîi-nǎi","thai":"ที่ไหน"},"x0":{"thai":"คน","roman":"kon"},"x1":{"thai":"น้องชาย","roman":"nɔ́ɔng-chaai"}},"poolOrder":["x1","a","b","c","x0"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.83"},{"id":"rp-189","type":"reply","context":[{"speaker":"M","thai":"ตาอยู่ที่ไหน","parts":["ตา","อยู่","ที่ไหน"],"roman":"taa yùu thîi-nǎi","english":"Where is grandpa?"}],"replySpeaker":"F","thai":"ตาอยู่บ้าน","roman":"taa yùu bâan","english":"Grandpa is at home.","options":[{"thai":"มีลูกสามคน","roman":"mii lûuk sǎam kon","correct":false},{"thai":"ตาอยู่บ้าน","roman":"taa yùu bâan","correct":true},{"thai":"ยาย","roman":"yaai","correct":false}],"source":"Essential Thai (Higbie), p.83","parts":["ตา","อยู่","บ้าน"]},{"id":"match-190","type":"match","pairs":[{"thai":"ที่นี่","roman":"thîi-nîi","english":"here"},{"thai":"บ้าน","roman":"bâan","english":"home / house"},{"thai":"ยาย","roman":"yaai","english":"grandmother (lit. mother's mother)"},{"thai":"ตา","roman":"taa","english":"grandfather (lit. mother's father)"}],"source":"Essential Thai (Higbie), p.83"}]$j$::jsonb),
  ($q$f08$q$, $q$family$q$, 7, $q$Uncles, aunts, and partners$q$, $j$[{"id":"wi-107","type":"wordIntro","word":{"thai":"ลุง","roman":"lung","english":"uncle (lit. parents' older brother)"},"source":"Essential Thai (Higbie), p.83"},{"id":"mc-191","type":"translationChoice","thai":"ลุงอยู่ที่ไหน","roman":"lung yùu thîi-nǎi","options":[{"text":"My aunt is at home.","correct":false},{"text":"My uncle and aunt are here.","correct":false},{"text":"He's/she's my partner.","correct":false},{"text":"Where is your uncle?","correct":true}],"source":"Essential Thai (Higbie), p.83","parts":["ลุง","อยู่","ที่ไหน"]},{"id":"sp-196","type":"speak","thai":"ลุงอยู่ที่ไหน","roman":"lung yùu thîi-nǎi","meaning":"Where is your uncle?","source":"Essential Thai (Higbie), p.83","parts":["ลุง","อยู่","ที่ไหน"]},{"id":"wi-108","type":"wordIntro","word":{"thai":"ป้า","roman":"pâa","english":"aunt (lit. parents' older sister)"},"source":"Essential Thai (Higbie), p.83"},{"id":"so-192","type":"sentenceOrder","prompt":"My aunt is at home.","tileUnit":"word","words":{"a":{"roman":"pâa","thai":"ป้า"},"b":{"roman":"yùu","thai":"อยู่"},"c":{"roman":"bâan","thai":"บ้าน"},"x0":{"thai":"พี่สาว","roman":"phîi-sǎao"},"x1":{"thai":"ลุง","roman":"lung"}},"poolOrder":["a","c","b","x0","x1"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.83"},{"id":"mc-193","type":"translationChoice","thai":"ลุงกับป้าอยู่ที่นี่","roman":"lung gàp pâa yùu thîi-nîi","options":[{"text":"Where is your uncle?","correct":false},{"text":"My uncle and aunt are here.","correct":true},{"text":"My aunt is at home.","correct":false},{"text":"He's/she's my partner.","correct":false}],"source":"Essential Thai (Higbie), p.83","parts":["ลุง","กับ","ป้า","อยู่","ที่นี่"]},{"id":"wi-114","type":"wordIntro","word":{"thai":"น้า","roman":"náa","english":"aunt/uncle (lit. mother's younger sibling)"},"source":"Essential Thai (Higbie), p.83"},{"id":"so-195","type":"sentenceOrder","prompt":"My aunt/uncle is at home.","tileUnit":"wor