  ($q$f09$q$, $q$family$q$, 8, $q$Married yet? Already or not$q$, $j$[{"id":"rule-121","type":"rule","title":"Married yet?","body":"Marriage is considered inevitable in Thai, so instead of asking \"Are you married?\" people ask \"Are you married yet?\" using rɯ́-yang at the end of the question.","source":"Essential Thai (Higbie), p.84"},{"id":"wi-122","type":"wordIntro","word":{"thai":"แต่งงาน","roman":"tɛ̀ng-ngaan","english":"to marry"},"source":"Essential Thai (Higbie), p.83"},{"id":"wi-123","type":"wordIntro","word":{"thai":"รึยัง","roman":"rɯ́-yang","english":"...yet?"},"source":"Essential Thai (Higbie), p.40"},{"id":"mc-199","type":"translationChoice","thai":"คุณแต่งงานรึยัง","roman":"khun tɛ̀ng-ngaan rɯ́-yang","options":[{"text":"Yes, I'm married.","correct":false},{"text":"Are you married yet?","correct":true},{"text":"Do you have a partner yet?","correct":false},{"text":"Do you have children yet?","correct":false}],"source":"Essential Thai (Higbie), p.84","parts":["คุณ","แต่งงาน","รึยัง"]},{"id":"mc-201","type":"translationChoice","thai":"มีแฟนรึยัง","roman":"mii fɛɛn rɯ́-yang","options":[{"text":"Do you have children yet?","correct":false},{"text":"Do you have a partner yet?","correct":true},{"text":"Are you married yet?","correct":false},{"text":"Yes, I'm married.","correct":false}],"source":"Essential Thai (Higbie), p.84","parts":["มี","แฟน","รึยัง"]},{"id":"sp-202","type":"speak","thai":"มีลูกรึยัง","roman":"mii lûuk rɯ́-yang","meaning":"Do you have children yet?","source":"Essential Thai (Higbie), p.84","parts":["มี","ลูก","รึยัง"]},{"id":"sp-204","type":"speak","thai":"คุณแต่งงานรึยัง","roman":"khun tɛ̀ng-ngaan rɯ́-yang","meaning":"Are you married yet?","source":"Essential Thai (Higbie), p.84","parts":["คุณ","แต่งงาน","รึยัง"]},{"id":"wi-128","type":"wordIntro","word":{"thai":"แล้ว","roman":"láew","english":"already"},"source":"Essential Thai (Higbie), p.40"},{"id":"so-200","type":"sentenceOrder","prompt":"Yes, I'm married.","tileUnit":"word","words":{